    // The required time is zero for less than three people,
    // otherwise it follows the pattern 2,4,6 for N=4,5,6 respectively.
    if (N < 3) {
        return 0;
    }
    // Time needed grows linearly with N: time = 2 * (N - 3)
    return 2 * (N - 3);
}

