public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        res.add(new ArrayList<>());
        return res;
    }
    List<Integer> current = new ArrayList<>();
    for (int num : nums) current.add(num);
    res.add(new ArrayList<>(current));
    int n = nums.length;
    if (n <= 1) return res;
    int[] c = new int[n];
    int i = 0;
    while (i < n) {
        if (c[i] < i) {
            if (i % 2 == 0) {
                Collections.swap(current, 0, i);
            } else {
                Collections.swap(current, c[i], i);
            }
            res.add(new ArrayList<>(current));
            c[i]++;
            i = 0;
        } else {
            c[i] = 0;
            i++;
        }
    }
    return res;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // If any string is empty, no substring of positive length can be common to all.
    for (String s : strings) {
        if (s == null || s.isEmpty()) {
            return 0;
        }
    }

    // If only one string, the answer is its length.
    if (strings.size() == 1) {
        return strings.get(0).length();
    }

    String first = strings.get(0);
    int maxLen = first.length();
    int low = 1;
    int high = maxLen;
    int best = 0;

    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (existsCommonSubstring(strings, first, mid)) {
            best = mid;
            low = mid + 1; // try longer
        } else {
            high = mid - 1; // try shorter
        }
    }
    return best;
}

private boolean existsCommonSubstring(List<String> strings, String first, int L) {
    int n = first.length();
    Set<String> candidates = new HashSet<>();
    for (int i = 0; i <= n - L; i++) {
        candidates.add(first.substring(i, i + L));
    }

    for (String candidate : candidates) {
        String rev = reverse(candidate);
        boolean ok = true;
        for (int idx = 1; idx < strings.size(); idx++) {
            String s = strings.get(idx);
            if (!(s.contains(candidate) || s.contains(rev))) {
                ok = false;
                break;
            }
        }
        if (ok) {
            return true;
        }
    }
    return false;
}

private String reverse(String s) {
    return new StringBuilder(s).reverse().toString();
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Find the shortest string to limit the maximum possible length
    String first = strings.get(0);
    if (first == null) first = "";
    int minLen = first.length();
    for (String s : strings) {
        if (s == null) continue;
        minLen = Math.min(minLen, s.length());
    }

    // Helper to check presence of a substring or its reverse in all strings
    java.util.function.Predicate<String> existsInAll = substr -> {
        String rev = new StringBuilder(substr).reverse().toString();
        for (String t : strings) {
            if (t == null) {
                return false;
            }
            if (!(t.contains(substr) || t.contains(rev))) {
                return false;
            }
        }
        return true;
    };

    // Iterate from the largest possible length downwards
    for (int len = minLen; len >= 1; --len) {
        // Generate all substrings of 'first' with length 'len'
        Set<String> seen = new HashSet<>();
        for (int i = 0; i <= first.length() - len; ++i) {
            String candidate = first.substring(i, i + len);
            if (!seen.add(candidate)) {
                continue; // Skip duplicate substrings
            }
            if (existsInAll.test(candidate)) {
                return len;
            }
        }
    }

    // No common substring (or its reverse) found
    return 0;
}

public int findLargestSubstring(java.util.List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    int n = strings.size();
    String first = strings.get(0);
    int minLen = first.length();
    for (int i = 1; i < n; i++) {
        int len = strings.get(i).length();
        if (len < minLen) {
            minLen = len;
        }
    }
    if (minLen == 0) {
        return 0;
    }
    String revFirst = new StringBuilder(first).reverse().toString();

    for (int len = minLen; len >= 1; len--) {
        java.util.HashSet<String> candidates = new java.util.HashSet<>();
        // substrings from the first string
        for (int i = 0; i + len <= first.length(); i++) {
            candidates.add(first.substring(i, i + len));
        }
        // substrings from the reverse of the first string
        for (int i = 0; i + len <= revFirst.length(); i++) {
            candidates.add(revFirst.substring(i, i + len));
        }

        outerLoop:
        for (String cand : candidates) {
            String revCand = new StringBuilder(cand).reverse().toString();
            for (int sIdx = 0; sIdx < n; sIdx++) {
                String s = strings.get(sIdx);
                if (!s.contains(cand) && !s.contains(revCand)) {
                    continue outerLoop;
                }
            }
            return len;
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Treat any null element as an empty string – it will force the result to 0.
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
    }

    String first = strings.get(0);
    int maxLen = first.length();

    for (int len = maxLen; len >= 1; len--) {
        for (int start = 0; start + len <= maxLen; start++) {
            String candidate = first.substring(start, start + len);
            String reverseCandidate = new StringBuilder(candidate).reverse().toString();

            boolean allContain = true;
            for (String s : strings) {
                if (!(s.contains(candidate) || s.contains(reverseCandidate))) {
                    allContain = false;
                    break;
                }
            }
            if (allContain) {
                return len;
            }
        }
    }
    return 0;
}

