                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;

                while (!stack.isEmpty()) {
                    int[] cur = stack.pop();
                    int curR = cur[0];
