    // Directions for 8-way connectivity
    final int[] dRow = {-1, -1, -1, 0, 0, 1, 1, 1};
    final int[] dCol = {-1, 0, 1, -1, 1, -1, 0, 1};

    // Create visited arrays with possibly varying row lengths
    boolean[][] visited = new boolean[rows][];
    for (int i = 0; i < rows; i++) {
        if (grid[i] != null) {
            visited[i] = new boolean[grid[i].length];
        } else {
            visited[i] = new boolean[0]; // Empty row
        }
    }

    int deposits = 0;

    for (int i = 0; i < rows; i++) {
        if (grid[i] == null) {
            continue;
        }
        for (int j = 0; j < grid[i].length; j++) {
            try {
                if (grid[i][j] == '@' && !visited[i][j]) {
                    deposits++;
                    // Iterative DFS using a stack
                    java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
                    stack.push(new int[]{i, j});
                    visited[i][j] = true;

                    while (!stack.isEmpty()) {
                        int[] cell = stack.pop();
                        int r = cell[0];
                        int c = cell[1];

                        for (int k = 0; k < 8; k++) {
                            int nr = r + dRow[k];
                            int nc = c + dCol[k];
                            if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].length) {
                                if (!visited[nr][nc] && grid[nr][nc] == '@') {
                                    visited[nr][nc] = true;
                                    stack.push(new int[]{nr, nc});
                                }
                            }
                        }
                    }
                }
            } catch (Exception e) {
                // If any unexpected runtime issue occurs for a specific cell, skip it
                continue;
            }
        }
    }
    return deposits;
}

public static int maxRegions(int N) {
    if (N <= 0) {
        // If there are no triangles, the plane remains undivided, so there is exactly one region.
        return 1;
    }
    // The formula 4N^2 - 6N + 4 fits the known sequence for maximum regions created by N triangles.
    // To avoid integer overflow, check that N is within the safe range for int computation.
    // Integer.MAX_VALUE ≈ 2.14×10^9, so 4*N^2 must not exceed this.
    // Solve 4*N^2 <= Integer.MAX_VALUE => N <= floor(sqrt(Integer.MAX_VALUE/4)) ≈ 23170.
    if (N > 23170) {
        throw new IllegalArgumentException("N is too large to compute accurately with int precision");
    }
    long result = 4L * N * N - 6L * N + 4L;
    return (int) result;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("N must be non-negative");
    }
    if (N == 0) {
        return 1; // No triangles, only the whole plane
    }
    long n = N;
    long result = 3 * n * n - 3 * n + 2;
    if (result > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds int range");
    }
    return (int) result;
}

