public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to string key
    java.util.function.Function<int[], String> coordKey = (int[] c) -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < c.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(c[i]);
        }
        return sb.toString();
    };

    // Edge case: start equals end
    if (java.util.Arrays.equals(start, end)) {
        return "can be travelled";
    }

    // Build adjacency map from given paths
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path == null) continue;
        if (path.length != 2 * n) continue; // invalid path, skip
        int[] a = new int[n];
        int[] b = new int[n];
        System.arraycopy(path, 0, a, 0, n);
        System.arraycopy(path, n, b, 0, n);
        String ka = coordKey.apply(a);
        String kb = coordKey.apply(b);
        adj.computeIfAbsent(ka, k -> new java.util.ArrayList<>()).add(kb);
        adj.computeIfAbsent(kb, k -> new java.util.ArrayList<>()).add(ka);
    }

    // Ensure start and end nodes are in the map for BFS (even if isolated)
    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);
    adj.computeIfAbsent(startKey, k -> new java.util.ArrayList<>());
    adj.computeIfAbsent(endKey, k -> new java.util.ArrayList<>());

    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (start == null || end == null || paths == null) return "cannot be travelled";
        if (start.length != n || end.length != n) return "cannot be travelled";
        java.util.function.Function<int[], String> coordToStr = coord -> {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < coord.length; i++) {
                if (i > 0) sb.append(',');
                sb.append(coord[i]);
            }
            return sb.toString();
        };
        String startKey = coordToStr.apply(start);
        String endKey   = coordToStr.apply(end);
        if (startKey.equals(endKey)) return "can be travelled";

        java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
        for (int[] p : paths) {
            if (p == null || p.length == 0) continue;
            if (p.length == 2) { // node indices
                // if indices out of bounds, skip
                int a = p[0], b = p[1];
                if (a < 0 || b < 0) continue;
                String sa = Integer.toString(a);
                String sb = Integer.toString(b);
                graph.computeIfAbsent(sa, k -> new java.util.ArrayList<>()).add(sb);
                graph.computeIfAbsent(sb, k -> new java.util.ArrayList<>()).add(sa);
            } else if (p.length == 2 * n) { // coordinate pairs
                int[] coordA = new int[n];
                int[] coordB = new int[n];
                System.arraycopy(p, 0, coordA, 0, n);
                System.arraycopy(p, n, coordB, 0, n);
                String sa = coordToStr.apply(coordA);
                String sb = coordToStr.apply(coordB);
                graph.computeIfAbsent(sa, k -> new java.util.ArrayList<>()).add(sb);
                graph.computeIfAbsent(sb, k -> new java.util.ArrayList<>()).add(sa);
            } else {
                // unsupported format; ignore
            }
        }

        java.util.Queue<String> queue = new java.util.ArrayDeque<>();
        java.util.Set<String> visited = new java.util.HashSet<>();
        queue.offer(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            String cur = queue.poll();
            java.util.List<String> neighbors = graph.get(cur);
            if (neighbors == null) continue;
            for (String nb : neighbors) {
                if (visited.contains(nb)) continue;
                if (nb.equals(endKey)) return "can be travelled";
                visited.add(nb);
                queue.offer(nb);
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

