public static String convertDatesToWeekdays(String date) {
    if (date == null) {
        return "Invalid input";
    }
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        return "Invalid input";
    }
    int month, day, year;
    try {
        month = Integer.parseInt(parts[0]);
        day = Integer.parseInt(parts[1]);
        year = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        return "Invalid input";
    }
    if (month < 1 || month > 12 || day < 1 || day > 31) {
        return "Invalid input";
    }
    java.util.GregorianCalendar cal = new java.util.GregorianCalendar(year, month - 1, day);
    if (cal.get(java.util.Calendar.MONTH) != month - 1 || cal.get(java.util.Calendar.DAY_OF_MONTH) != day) {
        return "Invalid input";
    }
    int w = cal.get(java.util.Calendar.DAY_OF_WEEK);
    String[] weekdays = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
    String[] months = {"January", "February", "March", "April", "May", "June", "July",
                       "August", "September", "October", "November", "December"};
    String monthName = months[month - 1];
    String weekdayName = weekdays[w - 1];
    return String.format("%s %d, %d is a %s", monthName, day, year, weekdayName);
}

