public static String convertDatesToWeekdays(String date) {
    if (date == null) return "Invalid date";
    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) return "Invalid date";
    try {
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        int year = Integer.parseInt(parts[2]);

        java.time.LocalDate localDate = java.time.LocalDate.of(year, month, day);
        java.time.Month monthObj = localDate.getMonth();
        String monthName = monthObj.getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);
        String dayOfWeek = localDate.getDayOfWeek().getDisplayName(java.time.format.TextStyle.FULL, java.util.Locale.ENGLISH);

        return String.format("%s %d, %d is a %s", monthName, day, year, dayOfWeek);
    } catch (Exception e) {
        return "Invalid date";
    }
}

public int[] twoSum(int[] nums, int target) {
    // Validate input: return null if the array is null or has less than two elements
    if (nums == null || nums.length < 2) {
        return null;
    }

    // Use a hash map to store value -> index for quick complement lookup
    java.util.Map<Integer, Integer> indexMap = new java.util.HashMap<>();

    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (indexMap.containsKey(complement)) {
            // Found the pair: return indices in any order
            return new int[]{indexMap.get(complement), i};
        }
        // Store the current value and its index
        indexMap.put(nums[i], i);
    }

    // If no pair is found, the problem statement guarantees this won't happen,
    // but we return null to indicate no solution in case of malformed input.
    return null;
}

