public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int trim = n / 20; // 5% of n, floor
    // Sorting the array to easily discard extremes
    java.util.Arrays.sort(arr);
    double sum = 0.0;
    for (int i = trim; i < n - trim; i++) {
        sum += arr[i];
    }
    int validCount = n - 2 * trim;
    return sum / validCount;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int k = n / 20; // number of elements to trim from each side (5%)
    // If k is zero, return mean of entire array
    if (k == 0) {
        double total = 0;
        for (int val : arr) {
            total += val;
        }
        return total / n;
    }
    // Sort the array to easily trim extremes
    java.util.Arrays.sort(arr);
    int remaining = n - 2 * k;
    if (remaining <= 0) {
        return 0.0; // no elements left to average
    }
    double sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += arr[i];
    }
    return sum / remaining;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty.");
    }
    int n = arr.length;
    int k = n / 20; // remove 5% from each side
    if (k * 2 >= n) {
        // In case of very small arrays where removing 5% each side results in zero elements,
        // we simply return the mean of the original array.
        double total = 0;
        for (int val : arr) total += val;
        return total / n;
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    double sum = 0.0;
    for (int i = k; i < n - k; i++) {
        sum += sorted[i];
    }
    return sum / (double)(n - 2 * k);
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int removeCount = n / 20;          // 5% of the elements
    if (removeCount == 0) {            // If less than 20 elements
        long total = 0;
        for (int val : arr) {
            total += val;
        }
        return total / (double) n;
    }
    java.util.Arrays.sort(arr);
    long sum = 0;
    int start = removeCount;
    int end = n - removeCount;         // exclusive
    int count = end - start;           // number of elements to average
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }
    return sum / (double) count;
}

