    double sum = 0.0;
    for (int i = n; i < arr.length - n; i++) {
        sum += arr[i];
    }
    int count = arr.length - 2 * n;
    return sum / count;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // Check other remainders
    for (int r = 1; r < k; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Validate input
    if (arr == null || k <= 0 || arr.length % 2 != 0) {
        return false;
    }

    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }

    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }

    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }

    int mid = k / 2;
    for (int r = 1; r <= mid; r++) {
        if (k % 2 == 0 && r == mid) {
            // already checked k/2 for even k
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Validate inputs
    if (arr == null || k <= 0) {
        return false;
    }
    int n = arr.length;
    // Must be even to pair all elements
    if (n % 2 != 0) {
        return false;
    }
    // Frequency array for remainders modulo k
    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k;
        }
        freq[r]++;
    }
    // Remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must also have even count
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For all other remainders, freq[r] must equal freq[k - r]
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) {
            // This case handled above for k even
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k == 0) {
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        return false;
    }

    // Use absolute value of k to avoid negative array size
    k = Math.abs(k);
    int[] freq = new int[k];

    for (int num : arr) {
        int rem = ((num % k) + k) % k; // ensures non‑negative remainder
        freq[rem]++;
    }

    // Remainder 0 elements must pair among themselves
    if (freq[0] % 2 != 0) {
        return false;
    }

    for (int r = 1; r <= k / 2; r++) {
        if (k % 2 == 0 && r == k / 2) {
            // When k is even, k/2 elements must pair among themselves
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            // For all other remainders, counts must match complementary remainder
            if (freq[r] != freq[k - r]) {
                return false;
            }
        }
    }

    return true;
}

