        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0) return 0;
    if (hasApple == null || hasApple.length != n) return 0;
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    if (edges != null) {
        for (int[] e : edges) {
            if (e == null || e.length != 2) continue;
            int u = e[0];
            int v = e[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            adj[u].add(v);
            adj[v].add(u);
        }
    }
    boolean[] visited = new boolean[n];
    int total = dfs(0, adj, hasApple, visited);
    return total;
}

private int dfs(int node, java.util.List<Integer>[] adj, boolean[] hasApple, boolean[] visited) {
    visited[node] = true;
    int time = 0;
    for (int nei : adj[node]) {
        if (!visited[nei]) {
            int childTime = dfs(nei, adj, hasApple, visited);
            if (childTime > 0 || hasApple[nei]) {
                time += childTime + 2;
            }
        }
    }
    return time;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null) {
        return 0;
    }
    if (edges.length != n - 1 || hasApple.length != n) {
        return 0;
    }
    // Build adjacency list
    java.util.ArrayList<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; ++i) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) continue;
        int u = e[0];
        int v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        graph[u].add(v);
        graph[v].add(u);
    }

    // Find parent of each node rooted at 0
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -2); // -2 indicates unvisited
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(0);
    parent[0] = -1;
    java.util.ArrayList<Integer> order = new java.util.ArrayList<>(n);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order.add(node);
        for (int nei : graph[node]) {
            if (parent[nei] == -2) {
                parent[nei] = node;
                stack.push(nei);
            }
        }
    }

    // Compute time required bottom‑up
    int[] subtreeTime = new int[n];
    for (int i = order.size() - 1; i > 0; i--) { // skip root at index 0
        int node = order.get(i);
        if (hasApple[node] || subtreeTime[node] > 0) {
            int p = parent[node];
            subtreeTime[p] += subtreeTime[node] + 2;
        }
    }
    return subtreeTime[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Basic validation
    if (n <= 0) return 0;
    if (edges == null) throw new IllegalArgumentException("Edges cannot be null");
    if (hasApple == null || hasApple.length != n) throw new IllegalArgumentException("hasApple array size mismatch");
    if (edges.length != n - 1) throw new IllegalArgumentException("Edges length must be n-1 for a tree");

    // Build adjacency list
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) throw new IllegalArgumentException("Each edge must have two integers");
        int u = e[0], v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) throw new IllegalArgumentException("Edge node indices out of bounds");
        graph[u].add(v);
        graph[v].add(u);
    }

    // DFS to count required edges
    int[] time = {0};
    java.util.function.BiFunction<Integer, Integer, Boolean> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Boolean apply(Integer node, Integer parent) {
            boolean has = hasApple[node];
            for (int child : graph[node]) {
                if (child == parent) continue;
                boolean childHas = apply(child, node);
                if (childHas) {
                    time[0] += 2;  // go to child and back
                    has = true;
                }
            }
            return has;
        }
    };

    dfs.apply(0, -1);
    return time[0];
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
        return 0;
    }
    java.util.ArrayList<Integer>[] g = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        g[i] = new java.util.ArrayList<Integer>();
    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) continue;
        int u = e[0], v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        g[u].add(v);
        g[v].add(u);
    }
    int[] time = new int[1];
    dfs(0, -1, hasApple, g, time);
    return time[0];
}

private boolean dfs(int node, int parent, boolean[] hasApple, java.util.ArrayList<Integer>[] g, int[] time) {
    boolean has = hasApple[node];
    for (int nei : g[node]) {
        if (nei == parent) continue;
        if (dfs(nei, node, hasApple, g, time)) {
            time[0] += 2;
            has = true;
        }
    }
    return has;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    if (n <= 0 || edges == null || hasApple == null || hasApple.length != n) {
