    }
    for (int[] e : edges) {
        if (e == null || e.length != 2) continue;
        int u = e[0];
        int v = e[1];
        if (u < 0 || u >= n || v < 0 || v >= n) continue;
        graph[u].add(v);
        graph[v].add(u);
    }
    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, java.util.List<Integer>[] graph, boolean[] hasApple) {
    int time = 0;
    for (int child : graph[node]) {
        if (child == parent) {
            continue;
        }
        int childTime = dfs(child, node, graph, hasApple);
        if (childTime > 0 || hasApple[child]) {
            time += childTime + 2;
        }
    }
    return time;
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int length = s.length();
    if (length == 0) {
        return "";
    }

    java.util.TreeMap<Character, Integer> counts = new java.util.TreeMap<>();
    for (int i = 0; i < length; ++i) {
        char c = s.charAt(i);
        Integer cnt = counts.get(c);
        counts.put(c, (cnt == null) ? 1 : cnt + 1);
    }

    StringBuilder result = new StringBuilder(length);

    while (!counts.isEmpty()) {
        // Ascending pass
        Character last = counts.firstKey();
        result.append(last);
        int cntLast = counts.get(last);
        if (cntLast == 1) {
            counts.remove(last);
        } else {
            counts.put(last, cntLast - 1);
        }

        while (true) {
            Character next = counts.higherKey(last);
            if (next == null) {
                break;
            }
            result.append(next);
            int cntNext = counts.get(next);
            if (cntNext == 1) {
                counts.remove(next);
            } else {
                counts.put(next, cntNext - 1);
            }
            last = next;
        }

        if (counts.isEmpty()) {
            break;
        }

        // Descending pass
        Character lastDesc = counts.lastKey();
        result.append(lastDesc);
        int cntLastDesc = counts.get(lastDesc);
        if (cntLastDesc == 1) {
            counts.remove(lastDesc);
        } else {
            counts.put(lastDesc, cntLastDesc - 1);
        }

        while (true) {
            Character prev = counts.lowerKey(lastDesc);
            if (prev == null) {
                break;
            }
            result.append(prev);
            int cntPrev = counts.get(prev);
            if (cntPrev == 1) {
                counts.remove(prev);
            } else {
                counts.put(prev, cntPrev - 1);
            }
            lastDesc = prev;
        }
    }

    return result.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        freq.put(c, freq.getOrDefault(c, 0) + 1);
    }
    StringBuilder sb = new StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending phase
        Character cur = freq.firstKey();
        sb.append(cur);
        int cnt = freq.get(cur);
        if (cnt == 1) {
            freq.remove(cur);
        } else {
            freq.put(cur, cnt - 1);
        }
        while (true) {
            Character next = freq.higherKey(cur);
            if (next == null) {
                break;
            }
            sb.append(next);
            cnt = freq.get(next);
            if (cnt == 1) {
                freq.remove(next);
            } else {
                freq.put(next, cnt - 1);
            }
            cur = next;
        }
        if (freq.isEmpty()) {
            break;
        }
        // Descending phase
        cur = freq.lastKey();
        sb.append(cur);
        cnt = freq.get(cur);
        if (cnt == 1) {
            freq.remove(cur);
        } else {
            freq.put(cur, cnt - 1);
        }
        while (true) {
            Character next = freq.lowerKey(cur);
            if (next == null) {
                break;
            }
            sb.append(next);
            cnt = freq.get(next);
            if (cnt == 1) {
                freq.remove(next);
            } else {
                freq.put(next, cnt - 1);
            }
            cur = next;
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return "";
    }
    int[] freq = new int[26];
    for (char ch : s.toCharArray()) {
        if (ch >= 'a' && ch <= 'z') {
            freq[ch - 'a']++;
        } else {
            // If characters outside 'a'-'z' are present, we can handle them
            // by adding them to a separate list or throwing an exception.
            // For simplicity, ignore such characters.
        }
    }
    int remaining = s.length();
    StringBuilder sb = new StringBuilder(remaining);
    while (remaining > 0) {
        // Ascending phase
        int i = 0;
        while (remaining > 0) {
            int j = i;
            while (j < 26 && freq[j] == 0) {
                j++;
            }
            if (j == 26) {
                break;
            }
            sb.append((char) ('a' + j));
            freq[j]--;
            remaining--;
            i = j + 1;
        }
        // Descending phase
        i = 25;
        while (remaining > 0) {
            int j = i;
            while (j >= 0 && freq[j] == 0) {
                j--;
            }
            if (j < 0) {
                break;
            }
            sb.append((char) ('a' + j));
            freq[j]--;
            remaining--;
            i = j - 1;
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.merge(c, 1, Integer::sum);
    }
    java.lang.StringBuilder sb = new java.lang.StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending part
        Character cur = freq.firstKey();
        while (cur != null) {
            sb.append(cur);
            int cnt = freq.get(cur) - 1;
            if (cnt == 0) {
                freq.remove(cur);
                cur = freq.higherKey(cur);
            } else {
                freq.put(cur, cnt);
                cur = freq.higherKey(cur);
            }
        }
        // Descending part (only if there are still characters left)
        if (!freq.isEmpty()) {
            cur = freq.lastKey();
            while (cur != null) {
                sb.append(cur);
                int cnt = freq.get(cur) - 1;
                if (cnt == 0) {
                    freq.remove(cur);
                    cur = freq.lowerKey(cur);
                } else {
                    freq.put(cur, cnt);
                    cur = freq.lowerKey(cur);
                }
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }

    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }

    int maxK = n / 2;
    // dp[k][s] == true if we can pick k elements that sum to s
    boolean[][] dp = new boolean[maxK + 1][totalSum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        // iterate k in descending order to avoid using the same element more than once
        for (int k = maxK - 1; k >= 0; k--) {
            for (int s = 0; s <= totalSum - num; s++) {
                if (dp[k][s]) {
                    dp[k + 1][s + num] = true;
                }
            }
        }
    }

    for (int k = 1; k <= maxK; k++) {
        long product = (long) totalSum * k;
        if (product % n != 0) {
            continue;
        }
        int target = (int) (product / n);
        if (dp[k][target]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    try {
        if (nums == null || nums.length <= 1) {
            return false;
        }
        int n = nums.length;
        long totalSum = 0L;
        for (int num : nums) {
            totalSum += num;
        }

        // sums[k] holds all possible sums of subsets of size k
        java.util.HashSet<Long>[] sums = new java.util.HashSet[n + 1];
        for (int i = 0; i <= n; i++) {
            sums[i] = new java.util.HashSet<Long>();
        }
        sums[0].add(0L);

        for (int num : nums) {
            // iterate k in reverse to avoid using the same element twice
            for (int k = n - 1; k >= 0; k--) {
                if (sums[k].isEmpty()) {
                    continue;
                }
                java.util.Set<Long> curr = sums[k];
                java.util.HashSet<Long> next = sums[k + 1];
                for (Long s : curr) {
                    next.add(s + num);
                }
            }
        }

        for (int k = 1; k < n; k++) {
            // target * n must equal totalSum * k for equal average
            long targetMul = totalSum * k;
            if (targetMul % n != 0) {
                continue;
            }
            long targetSum = targetMul / n;
            if (sums[k].contains(targetSum)) {
                return true;
            }
        }
        return false;
    } catch (Exception e) {
        // In case of any unexpected runtime issues, safely return false
        return false;
    }
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }

    // Map from subset size to set of achievable sums.
    Map<Integer, Set<Integer>> sizeToSums = new HashMap<>();
    sizeToSums.put(0, new HashSet<>(Collections.singletonList(0)));

    for (int num : nums) {
        // Create a snapshot to avoid concurrent modification.
        Map<Integer, Set<Integer>> snapshot = new HashMap<>(sizeToSums);
        for (Map.Entry<Integer, Set<Integer>> entry : snapshot.entrySet()) {
            int sz = entry.getKey();
            // Only consider subset sizes up to n/2 for efficiency.
            if (sz >= n / 2) {
                continue;
            }
            int newSize = sz + 1;
            Set<Integer> newSums = sizeToSums.computeIfAbsent(newSize, k -> new HashSet<>());
            for (int sum : entry.getValue()) {
                newSums.add(sum + num);
            }
        }
    }

    // Check for any valid partition.
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) {
            continue; // target sum must be integer.
        }
        int targetSum = (totalSum * k) / n;
        Set<Integer> sums = sizeToSums.get(k);
        if (sums != null && sums.contains(targetSum)) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
