    // use boolean 2D array: dp[k][s] == true if sum s achievable with subset size k
    boolean[][] dp = new boolean[n + 1][sum + 1];
    dp[0][0] = true;
    for (int num : nums) {
        // iterate k in reverse to avoid reuse of same number
        for (int k = n - 1; k >= 0; k--) {
