}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    // Try all subset sizes from 1 to n/2
    for (int k = 1; k <= n / 2; k++) {
        if ((sum * k) % n != 0) {
            continue; // target sum must be integer
        }
        int target = (sum * k) / n;
        if (canFind(nums, target, k)) {
            return true;
        }
    }
    return false;
}

private boolean canFind(int[] nums, int target, int k) {
    @SuppressWarnings("unchecked")
    java.util.Set<Integer>[] dp = new java.util.HashSet[k + 1];
    for (int i = 0; i <= k; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        for (int size = k - 1; size >= 0; size--) {
            for (int s : dp[size]) {
                dp[size + 1].add(s + num);
            }
        }
    }
    return dp[k].contains(target);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0; // Already at the top
    }
    if (n == 1) {
        return cost[0];
    }

    int prevPrev = cost[0];          // dp[0]
    int prev = cost[1];              // dp[1]
    int curr = 0;

    for (int i = 2; i < n; i++) {
        curr = Math.min(prev, prevPrev) + cost[i];
        prevPrev = prev;
        prev = curr;
    }

    return Math.min(prev, prevPrev);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        throw new IllegalArgumentException("cost array must not be null or empty");
    }
    int n = cost.length;
    if (n == 1) {
        // Only one step, start on it and climb out
        return cost[0];
    }
    // dp[i] represents the minimum cost to reach step i
    int prev2 = cost[0]; // dp[0]
    int prev1 = cost[1]; // dp[1]
    for (int i = 2; i < n; i++) {
        int curr = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = curr;
    }
    // To reach the top, one can come from step n-1 or n-2
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input gracefully
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // dp[i] is represented by prev1 (dp[i-1]) and prev2 (dp[i-2])
    int prev2 = 0; // dp[0] = 0  (starting at step 0 without paying)
    int prev1 = 0; // dp[1] = 0  (starting at step 1 without paying)
    for (int i = 2; i <= n; i++) {
        // At step i (top is after step n), compute minimal cost to reach it
        int costFromPrev1 = prev1 + cost[i - 1]; // move from step i-1
        int costFromPrev2 = prev2 + cost[i - 2]; // move from step i-2
        int curr = Math.min(costFromPrev1, costFromPrev2);
        prev2 = prev1;
        prev1 = curr;
    }
    // prev1 now holds dp[n] → minimal cost to reach the top
    return prev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null.");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    int prev2 = cost[0]; // dp[0]
    int prev1 = cost[1]; // dp[1]
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

