public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || s.length() < k) {
        return false;
    }
    int required = 1 << k;
    // If there are not enough substrings to cover all possible codes
    if (required > s.length() - k + 1) {
        return false;
    }
    boolean[] seen = new boolean[required];
    int mask = required - 1;
    int code = 0;
    // Build the first code of length k
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int distinct = 1;

    for (int i = k; i < s.length(); i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[code]) {
            seen[code] = true;
            distinct++;
            if (distinct == required) {
                return true;
            }
        }
    }
    return distinct == required;
}

public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null || k <= 0) return false;
    int n = s.length();
    if (n < k) return false;

    // Prevent shift overflow for large k
    if (k >= 63) return false;

    long totalCodes = 1L << k;
    if ((long) n - k + 1 < totalCodes) return false;

    if (k <= 20) {
        int size = 1 << k;
        boolean[] seen = new boolean[size];
        int mask = size - 1;
        int code = 0;
        for (int i = 0; i < n; i++) {
            code = ((code << 1) & mask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                seen[code] = true;
            }
        }
        for (boolean b : seen) {
            if (!b) return false;
        }
        return true;
    } else {
        java.util.HashSet<Long> seen = new java.util.HashSet<>();
        long mask = (1L << k) - 1;
        long code = 0;
        for (int i = 0; i < n; i++) {
            code = ((code << 1) & mask) | (s.charAt(i) - '0');
            if (i >= k - 1) {
                seen.add(code);
                if (seen.size() == totalCodes) {
                    return true;
                }
            }
        }
        return seen.size() == totalCodes;
    }
}

