    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    if (k >= 31) { // too many codes to handle reasonably
        return false;
    }
    int target = 1 << k;
    java.util.HashSet<Integer> seen = new java.util.HashSet<>(target);
    int mask = 0;
    int maskLimit = target - 1;
    for (int i = 0; i < n; i++) {
        int bit = s.charAt(i) - '0';
        mask = ((mask << 1) & maskLimit) | bit;
        if (i >= k - 1) {
            seen.add(mask);
            if (seen.size() == target) {
                return true;
            }
        }
    }
    return seen.size() == target;
}

public boolean hasAllCodes(String s, int k) {
    if (k <= 0) {
        // By definition, the only binary string of length 0 is the empty string,
        // which is trivially a substring of any string.
        return true;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    // If k is too large to produce 2^k distinct codes that can fit in an int,
    // or if the number of distinct codes (2^k) is larger than the number
    // of possible windows in s, then it's impossible.
    if (k > 31) { // 1 << k would overflow
        return false;
    }
    long totalLL = 1L << k;
    if (totalLL > (long)n - k + 1) {
        return false;
    }
    int total = 1 << k;          // size of the bitset
    boolean[] seen = new boolean[total];
    int mask = total - 1;        // keeps only the last k bits
    int code = 0;
    // Build the initial window of length k
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int count = 1;
    // Slide through the string, updating the code in O(1) per step
    for (int i = k; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == total) {
                return true;
            }
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null || k <= 0) {
        return false;
    }
    int n = s.length();
    // Not enough length to contain all k-length substrings
    if (n < k) {
        return false;
    }
    // Limit k to avoid integer overflow and excessive memory usage
    // 2^k should be within reasonable bounds for int arrays
    if (k > 20) { // 2^20 = 1,048,576, manageable
        return false;
    }
    int total = 1 << k; // total number of distinct binary strings of length k
    boolean[] seen = new boolean[total];
    int seenCount = 0;
    int window = 0;
    int mask = total - 1; // to keep only k bits

    for (int i = 0; i < n; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            // Invalid character encountered
            return false;
        }
        // Shift left and add new bit
        window = ((window << 1) & mask) | (c == '1' ? 1 : 0);
        if (i >= k - 1) {
            if (!seen[window]) {
                seen[window] = true;
                seenCount++;
                if (seenCount == total) {
                    return true; // all possible codes found
                }
            }
        }
    }
    return false;
}

