public int minOperations(int n) {
    // Validate input: non-positive n yields no operations
    if (n <= 0) {
        return 0;
    }
    try {
        // t = floor((n - 1) / 2)
        int t = (n - 1) / 2;
        long part1 = (long) (t + 1);
        long part2 = (long) (n - t - 1);
        long ops = part1 * part2;
        // Clamp result to int range
        if (ops > Integer.MAX_VALUE) {
            throw new ArithmeticException("Result exceeds maximum int value");
        }
        return (int) ops;
    } catch (Exception e) {
        // In case of unexpected errors, return -1 or rethrow
        return -1;
    }
}

