        int surplus = (2 * i + 1) - n;
        if (surplus > 0) {
            operations += surplus;
        }
    }
    if (operations > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds int range");
    }
    return (int) operations;
}

