    }
    long start = ((n - 1) / 2L) + 1;      // first index with a surplus
    long count = (long) n - start;       // number of surplus indices
    long ops = start * count;             // total number of unit transfers
    if (ops > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds allowable int range");
    }
    return (int) ops;
}

