public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long maxEnding = nums[0];
    long maxSoFar = nums[0];
    long minEnding = nums[0];
    long minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        // For maximum subarray sum
        maxEnding = Math.max(nums[i], maxEnding + nums[i]);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        // For minimum subarray sum
        minEnding = Math.min(nums[i], minEnding + nums[i]);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    long result = Math.max(maxSoFar, Math.abs(minSoFar));
    // Since the method signature expects an int, cast carefully
    return (int) result;
}

