public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    int[] fib = new int[50];
    fib[0] = 1;
    fib[1] = 1;
    int size = 2;
    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        if (next > k) {
            break;
        }
        fib[size++] = next;
    }
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

