            if (counterpart != i) {
                large.add(counterpart);
            }
        }
    }
    int totalFactors = small.size() + large.size();
    if (k > totalFactors) {
        return -1;
    }
    // Build the kth factor directly
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        // In large list, the factors are in descending order; we need ascending.
        int idx = k - small.size() - 1;
        return large.get(large.size() - 1 - idx);
    }
}

