public int kthFactor(int n, int k) {
    // Validate inputs: n and k must be positive integers
    if (n <= 0 || k <= 0) {
        return -1;
    }

    // Collect small and large factors separately
    java.util.ArrayList<Integer> smallFactors = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> largeFactors = new java.util.ArrayList<>();

    // Iterate up to sqrt(n)
    for (int i = 1; (long) i * i <= n; i++) {
        if (n % i == 0) {
            smallFactors.add(i);
            int counterpart = n / i;
            if (counterpart != i) {
                largeFactors.add(counterpart);
            }
        }
    }

    // Combine factors in ascending order: smallFactors + sorted largeFactors
    java.util.ArrayList<Integer> allFactors = new java.util.ArrayList<>(smallFactors);
    java.util.Collections.sort(largeFactors);
    allFactors.addAll(largeFactors);

    // Return kth factor if it exists
    if (k <= allFactors.size()) {
        return allFactors.get(k - 1);
    } else {
        return -1;
    }
}

public int kthFactor(int n, int k) {
