    }
    // Use two lists: small factors in ascending order,
    // and large factors in descending order
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            if (i != n / i) {
                large.add(n / i); // will be in descending order as i increases
            }
        }
    }
    int totalFactors = small.size() + large.size();
    if (k > totalFactors) {
        return -1;
    }
    if (k <= small.size()) {
        return small.get(k - 1);
    }
    // Adjust k for remaining large factors
    int remaining = k - small.size();
    // large list is in descending order, so get the (remaining-1)th element from the end
    int indexFromEnd = remaining - 1;
    return large.get(large.size() - 1 - indexFromEnd);
}

