public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    final int n = s.length();
    final int[] maxCount = {0};

    class SplitHelper {
        void dfs(int index, java.util.Set<String> used) {
            if (index == n) {
                if (used.size() > maxCount[0]) {
                    maxCount[0] = used.size();
                }
                return;
            }
            for (int i = index + 1; i <= n; i++) {
                String sub = s.substring(index, i);
                if (!used.contains(sub)) {
                    used.add(sub);
                    dfs(i, used);
                    used.remove(sub);
                }
            }
        }
    }

    new SplitHelper().dfs(0, new java.util.HashSet<>());
    return maxCount[0];
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    final int n = s.length();
    // Using an array to hold the set so it can be modified inside the local class
    java.util.Set<String>[] setRef = new java.util.Set[] { new java.util.HashSet<String>() };

    class Solver {
        int dfs(int pos) {
            if (pos == n) return 0;
            int best = 0;
            for (int end = pos + 1; end <= n; end++) {
                String sub = s.substring(pos, end);
                if (!setRef[0].contains(sub)) {
                    setRef[0].add(sub);
                    int cur = 1 + dfs(end);
                    if (cur > best) best = cur;
                    setRef[0].remove(sub);
                }
            }
            return best;
        }
    }
    return new Solver().dfs(0);
}

