private static int dfs(int index, String s, java.util.Set<String> used) {
    if (index == s.length()) {
        return 0;
    }
    int best = -1;
    for (int i = index + 1; i <= s.length(); i++) {
        String sub = s.substring(index, i);
        if (!used.contains(sub)) {
            used.add(sub);
            int res = dfs(i, s, used);
            if (res != -1) {
                best = Math.max(best, 1 + res);
            }
            used.remove(sub);
        }
    }
    return best;
}

