private int max;

private void dfs(int idx, java.util.Set<String> used, String s) {
    if (idx == s.length()) {
        if (used.size() > max) {
            max = used.size();
        }
        return;
    }
    for (int i = idx; i < s.length(); i++) {
        String sub = s.substring(idx, i + 1);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(i + 1, used, s);
            used.remove(sub);
        }
    }
}

