public String getSmallestString(int n, int k) {
    // Validate input: minimum value is all 'a's (value 1 each)
    if (n <= 0 || k < n || k > 26 * n) {
        // Return empty string for invalid requests
        return "";
    }
    char[] result = new char[n];
    // Start with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int diff = k - n; // extra value needed beyond all 'a's
    // Distribute the extra value starting from the end (rightmost)
    for (int i = n - 1; i >= 0 && diff > 0; i--) {
        int add = Math.min(25, diff); // can increase by at most 25 ('z' - 'a')
        result[i] = (char) (result[i] + add);
        diff -= add;
    }
    return new String(result);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) {
