    // Using long to avoid overflow when computing 26*n
    long max = 26L * n;
    if (k < n || k > max) {
        throw new IllegalArgumentException("k must be between n and 26*n inclusive");
    }

    int remaining = k - n; // total extra value we need to distribute
    char[] result = new char[n];
    // Start with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    // Distribute the remaining value from the end towards the beginning
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // can add at most 25 to each character (1->26)
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

