        int nextDigitMinus = lastDigit - 1;
        if (nextDigitMinus >= 0) {
            int nextNumber = current * 10 + nextDigitMinus;
            if (nextNumber <= high) {
                queue.offer(nextNumber);
            }
        }
    }

    Collections.sort(result);
    return result;
}

