public static int countDigitOne(int n) {
    if (n < 0) {
        return 0; // No positive numbers to count
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);

        count += higher * factor;
        if (current == 1) {
            count += lower + 1;
        } else if (current > 1) {
            count += factor;
        }

        factor *= 10;
    }
    return (int) count;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0L;
    long position = 1L;
    while (position <= n) {
        long divider = position * 10L;
        long fullCycles = n / (int)divider;
        count += fullCycles * position;
        long remainder = n % (int)divider;
        long add = remainder - position + 1;
        if (add > 0) {
            if (add > position) {
                add = position;
            }
            count += add;
        }
        if (position > Long.MAX_VALUE / 10L) {
            break; // prevent overflow of the next multiplication
        }
        position *= 10L;
    }
    return (int)count;
}

