public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    // Determine the number of columns; ensure the first row is not null
    int n = 0;
    for (int[] row : mat) {
        if (row != null) {
            n = row.length;
            break;
        }
    }
    if (n == 0) {
        return 0;
    }

    int m = mat.length;
    int[][] hor = new int[m][n];
    int[][] ver = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;

    for (int i = 0; i < m; i++) {
        if (mat[i] == null) {
            continue; // Treat rows that are null as all zeros
        }
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                hor[i][j] = (j > 0) ? hor[i][j - 1] + 1 : 1;
                ver[i][j] = (i > 0) ? ver[i - 1][j] + 1 : 1;
                diag[i][j] = (i > 0 && j > 0) ? diag[i - 1][j - 1] + 1 : 1;
                anti[i][j] = (i > 0 && j < n - 1) ? anti[i - 1][j + 1] + 1 : 1;
                int currentMax = Math.max(
                        Math.max(hor[i][j], ver[i][j]),
                        Math.max(diag[i][j], anti[i][j])
                );
                if (currentMax > max) {
                    max = currentMax;
                }
            } else {
                hor[i][j] = 0;
                ver[i][j] = 0;
                diag[i][j] = 0;
                anti[i][j] = 0;
            }
        }
    }
    return max;
}

