                dp[i][j][1] = (i > 0 ? dp[i - 1][j][1] : 0) + 1;                           // vertical
                dp[i][j][2] = (i > 0 && j > 0 ? dp[i - 1][j - 1][2] : 0) + 1;              // diagonal
                dp[i][j][3] = (i > 0 && j + 1 < n ? dp[i - 1][j + 1][3] : 0) + 1;          // anti-diagonal
                int cellMax = Math.max(Math.max(dp[i][j][0], dp[i][j][1]),
                                       Math.max(dp[i][j][2], dp[i][j][3]));
                if (cellMax > maxLen) {
                    maxLen = cellMax;
                }
            } else {
                // mat[i][j] is 0, no need to set dp values since they are already 0
            }
        }
    }
    return maxLen;
}

