    return count[0];
}

private static void backtrack(int[] A, boolean[] used, int depth, int last, int[] count) {
    int n = A.length;
    if (depth == n) {
        count[0]++;
        return;
    }
    int prev = -1;
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (prev != -1 && A[i] == prev) continue;
        if (depth > 0 && !isPerfectSquare(A[i] + last)) continue;
        used[i] = true;
        backtrack(A, used, depth + 1, A[i], count);
        used[i] = false;
        prev = A[i];
    }
}

private static boolean isPerfectSquare(int sum) {
    int sqrt = (int) Math.sqrt(sum);
    return sqrt * sqrt == sum;
}

public static int squarePermutations(int[] A) {
    // Preprocess distinct values and frequencies
    int n = A.length;
    java.util.Arrays.sort(A);
    java.util.List<Integer> distinctList = new java.util.ArrayList<>();
    int[] freqOrig;
    {
        int len = 0;
        int last = -1;
        java.util.List<Integer> freqList = new java.util.ArrayList<>();
        for (int v : A) {
            if (v != last) {
                if (last != -1) {
                    freqList.add(len);
                }
                distinctList.add(v);
                len = 1;
                last = v;
            } else {
                len++;
            }
        }
        if (last != -1) freqList.add(len);
        int m = distinctList.size();
        freqOrig = new int[m];
        for (int i = 0; i < m; i++) freqOrig[i] = freqList.get(i);
    }
    int m = freqOrig.length;
    int[] vals = new int[m];
    for (int i = 0; i < m; i++) vals[i] = distinctList.get(i);

    // Precompute perfect square set up to max possible sum
    int maxVal = vals[m - 1];
    int maxSum = 2 * maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int k = 0; k * k <= maxSum; k++) isSquare[k * k] = true;

    // Precompute bases for key encoding
    int[] bases = new int[m];
    long prod = 1;
    for (int i = 0; i < m; i++) {
        bases[i] = (int) prod;
        prod *= (freqOrig[i] + 1);
    }
    long totalKey = prod - 1; // key when all counts used (all freq used so key=0)

    java.util.Map<Long, Long> memo = new java.util.HashMap<>();

    java.util.function.BiFunction<Integer, Long, Long> dfs = new java.util.function.BiFunction<>() {
        @Override
        public Long apply(Integer lastIdx, Long key) {
            long composite = (key << 4) | (lastIdx + 1);
            if (memo.containsKey(composite)) return memo.get(composite);
            if (key == 0) return 1L;
            long res = 0;
            for (int i = 0; i < m; i++) {
                // Check if any left of this value
                long idxMask = bases[i];
                if ((key & idxMask) == 0) continue; // no remaining
                if (lastIdx != -1 && !isSquare[vals[lastIdx] + vals[i]]) continue;
                long newKey = key - idxMask;
                res += apply(i, newKey);
            }
            memo.put(composite, res);
            return res;
        }
    };

    // Initial key: all frequencies remaining
    long initialKey = (long) totalKey;
    long result = dfs.apply(-1, initialKey);
    return (int) result;
}

public static int squarePermutations(int[] A) {
    if (A == null) {
        return 0;
    }
    int n = A.length;
    if (n == 0) {
        return 1;
    }
    // Sort to handle duplicates
    java.util.Arrays.sort(A);
    // Determine maximum possible sum for square lookup
    int maxVal = A[n - 1];
    int maxSum = maxVal + maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    boolean[] used = new boolean[n];
    class Counter {
        int count = 0;
    }
    Counter counter = new Counter();

    java.util.function.Consumer<java.util.function.BiConsumer<Integer, Integer>> dfs = new java.util.function.Consumer<java.util.function.BiConsumer<Integer, Integer>>() {
        @Override
        public void accept(java.util.function.BiConsumer<Integer, Integer> pair) {
            int pos = pair.applyAsInt(null, 0);
            int lastIdx = pair.applyAsInt(null, 1);

            if (pos == n) {
                counter.count++;
                return;
            }

            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                // Skip duplicates: only use the first unused instance in a group
                if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;

                if (pos > 0 && !isSquare[A[lastIdx] + A[i]]) continue;

                used[i] = true;
                // Pass new positions: next position is pos+1, new last index is i
                this.accept(pos + 1, i);
                used[i] = false;
            }
        }

        // Helper to mimic BiConsumer functional interface with two ints
        private int applyAsInt(Object ignored, int value) {
            return value;
        }
    };

    // Initiate DFS: start with position 0, lastIdx dummy -1
    dfs.accept(new java.util.function.BiConsumer<Integer, Integer>() {
        @Override
        public void accept(Integer x, Integer y) {}
    });

    return counter.count;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Sort array to handle duplicates
    int[] sorted = A.clone();
    java.util.Arrays.sort(sorted);
    // Precompute adjacency allowed matrix
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = sorted[i] + sorted[j];
            int s = (int) Math.sqrt(sum);
            if (s * s == sum) {
                can[i][j] = true;
            }
        }
    }
    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < (1 << n); i++) {
        java.util.Arrays.fill(dp[i], -1L);
    }
    java.util.function.LongBinaryOperator dfs = new java.util.function.LongBinaryOperator() {
        @Override
        public long applyAsLong(long maskLast, long unused) {
            int mask = (int) (maskLast >> 32);
            int last = (int) (maskLast & 0xffffffffL);
            if (mask == fullMask) {
                return 1;
            }
            long key = ((long) mask << 32) | ((long) last & 0xffffffffL);
            if (dp[mask][last] != -1L) {
                return dp[mask][last];
            }
            long res = 0;
            for (int nxt = 0; nxt < n; nxt++) {
                if ((mask & (1 << nxt)) != 0) continue;
                // skip duplicates
                if (nxt > 0 && sorted[nxt] == sorted[nxt - 1] && (mask & (1 << (nxt - 1))) == 0) continue;
                if (!can[last][nxt]) continue;
                int newMask = mask | (1 << nxt);
                res += dfs.applyAsLong(((long) newMask << 32) | ((long) nxt & 0xffffffffL), 0);
            }
            dp[mask][last] = res;
            return res;
        }
    };
    long total = 0;
    for (int start = 0; start < n; start++) {
        // skip duplicates for start position
        if (start > 0 && sorted[start] == sorted[start - 1]) continue;
        int mask = 1 << start;
        total += dfs.applyAsLong(((long) mask << 32) | ((long) start & 0xffffffffL), 0);
    }
    return (int) total;
}

public static int squarePermutations(int[] A) {
    if (A == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    int n = A.length;
    if (n == 0) {
        return 1;
    }
    java.util.Arrays.sort(A);
    java.util.HashMap<Long, Long> memo = new java.util.HashMap<>();
    long allUsed = (1L << n) - 1;
    return (int) dfs(0L, -1, A, allUsed, memo);
}

private static long dfs(long mask, int lastIdx, int[] A, long allUsed, java.util.HashMap<Long, Long> memo) {
    if (mask == allUsed) {
        return 1L;
    }
    long key = (mask << 5) | (lastIdx + 1); // +1 because lastIdx can be -1
    Long cached = memo.get(key);
    if (cached != null) {
        return cached;
    }
    long count = 0L;
    int n = A.length;
    for (int i = 0; i < n; i++) {
        long bit = 1L << i;
        if ((mask & bit) != 0) {
            continue; // already used
        }
        // skip duplicate values to avoid counting equivalent permutations
        if (i > 0 && A[i] == A[i - 1] && (mask & (1L << (i - 1))) == 0) {
            continue;
        }
        if (lastIdx >= 0) {
            int sum = A[lastIdx] + A[i];
            int r = (int) Math.round(Math.sqrt(sum));
            if (r * r != sum) {
                continue; // not a perfect square sum
            }
        }
        count += dfs(mask | bit, i, A, allUsed, memo);
        // If count may exceed int, keep as long
    }
    memo.put(key, count);
    return count;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = heights.length;
    if (n == 0) {
        return 0;
    }
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    long maxArea = 0L;
    for (int i = 0; i <= n; i++) {
        long currentHeight = (i < n) ? heights[i] : 0L;
        if (currentHeight < 0) {
            throw new IllegalArgumentException("Bar heights must be non-negative");
        }
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
