public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int index = 0;

    for (int d = 0; d <= m + n - 2; d++) {
        int row = d < m ? d : m - 1;
        int col = d < m ? 0 : d - (m - 1);

        if ((d & 1) == 0) { // even diagonal, move up-right
            while (row >= 0 && col < n) {
                result[index++] = mat[row][col];
                row--;
                col++;
            }
        } else { // odd diagonal, move down-left
            while (row < m && col >= 0) {
                result[index++] = mat[row][col];
                row++;
                col--;
            }
        }
    }

    return result;
}

