public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find the first index 'i' from the end where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // Digits are in non-increasing order; no larger permutation
        return -1;
    }

    // Find the first index 'j' from the end where digits[j] > digits[i]
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer, checking for overflow
    long result = 0;
    for (char c : digits) {
        result = result * 10 + (c - '0');
        if (result > Integer.MAX_VALUE) {
            return -1; // overflow in int range
        }
    }

    return (int) result;
}

