public static List<String> centerSymmetricNumbers(int n) {
    List<String> res = new ArrayList<>();
    if (n <= 0) return res;

    // mapping of digits to their mirror counterparts
    int[] firstDigits = {0, 1, 6, 8, 9};
    int[] mirrorDigits = {0, 1, 9, 8, 6};

    // helper to generate combinations for the first half
    int halfLen = n / 2;
    if (halfLen == 0) {
        // n == 1
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }

    // Build all possible first halves
    List<String> firstHalfList = new ArrayList<>();
    // start with first digit (cannot be 0 if n > 1)
    for (int i = 0; i < firstDigits.length; i++) {
        if (halfLen > 0 && firstDigits[i] == 0) continue;
        char firstChar = (char) ('0' + firstDigits[i]);
        firstHalfList.add(String.valueOf(firstChar));
    }

    // extend to full length of first half (halfLen)
    while (firstHalfList.size() > 0 && firstHalfList.get(0).length() < halfLen) {
        List<String> newList = new ArrayList<>();
        for (String prefix : firstHalfList) {
            for (int d : firstDigits) {
                newList.add(prefix + (char) ('0' + d));
            }
        }
        firstHalfList = newList;
    }

    // construct full numbers
    for (String firstHalf : firstHalfList) {
        if (n % 2 == 0) {
            // even length: mirror entire first half
            StringBuilder sb = new StringBuilder(firstHalf);
            for (int i = firstHalf.length() - 1; i >= 0; i--) {
                char c = firstHalf.charAt(i);
                int idx = c - '0';
                sb.append(mirrorDigits[idx]);
            }
            res.add(sb.toString());
        } else {
            // odd length: iterate over middle digits 0,1,8
            for (char mid : new char[]{'0', '1', '8'}) {
                StringBuilder sb = new StringBuilder(firstHalf);
                sb.append(mid);
                for (int i = firstHalf.length() - 1; i >= 0; i--) {
                    char c = firstHalf.charAt(i);
                    int idx = c - '0';
                    sb.append(mirrorDigits[idx]);
                }
                res.add(sb.toString());
            }
        }
    }

    return res;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    // Special case: single digit numbers
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }

    char[] num = new char[n];
    char[][] pairs = {
        {'0', '0'}, {'1', '1'}, {'8', '8'}, {'6', '9'}, {'9', '6'}
    };

    // Backtrack helper
    java.util.function.Consumer<Integer> backtrack = new java.util.function.Consumer<Integer>() {
        @Override
        public void accept(Integer pos) {
            if (pos >= n - pos - 1) {
                // All positions filled
                result.add(new String(num));
                return;
            }
            for (char[] pair : pairs) {
                // Skip leading zero for the first position
                if (pos == 0 && pair[0] == '0') {
                    continue;
                }
                num[pos] = pair[0];
                num[n - pos - 1] = pair[1];
                accept(pos + 1);
            }
        }
    };

    backtrack.accept(0);
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Length cannot be negative");
    }
    if (n == 0) {
        return new ArrayList<>();
    }
    return build(n, n);
}

private static List<String> build(int currentLen, int totalLen) {
    List<String> result = new ArrayList<>();
    if (currentLen == 0) {
        result.add("");
        return result;
    }
    if (currentLen == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    List<String> inner = build(currentLen - 2, totalLen);
    for (String s : inner) {
        if (currentLen == totalLen) {
            result.add("1" + s + "1");
            result.add("6" + s + "9");
            result.add("8" + s + "8");
            result.add("9" + s + "6");
        } else {
            result.add("0" + s + "0");
            result.add("1" + s + "1");
            result.add("6" + s + "9");
            result.add("8" + s + "8");
            result.add("9" + s + "6");
        }
    }
    return result;
}

