    }
    return buildStrobogrammatic(n, n);
}

private static List<String> buildStrobogrammatic(int currentLen, int origLen) {
    // Base cases
    if (currentLen == 0) {
        return new ArrayList<>(Collections.singletonList(""));
    }
    if (currentLen == 1) {
        return new ArrayList<>(Arrays.asList("0", "1", "8"));
    }

    // Recursive step: build inner strings first
    List<String> prev = buildStrobogrammatic(currentLen - 2, origLen);
    List<String> result = new ArrayList<>();

    for (String inner : prev) {
        // Leading zeros are only allowed when this is not the outermost level
        if (currentLen != origLen) {
            result.add("0" + inner + "0");
        }
        result.add("1" + inner + "1");
        result.add("6" + inner + "9");
        result.add("9" + inner + "6");
        result.add("8" + inner + "8");
    }

    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    char[][] pairs = { {'0','0'}, {'1','1'}, {'8','8'}, {'6','9'}, {'9','6'} };
    char[] middle = { '0', '1', '8' };
    char[] cur = new char[n];
    backtrack(result, cur, 0, n - 1, pairs, middle, n);
    return result;
}

private static void backtrack(List<String> result, char[] cur, int left, int right, char[][] pairs, char[] middle, int n) {
    if (left > right) {
        result.add(new String(cur));
        return;
    }
    if (left == right) {
        for (char m : middle) {
            cur[left] = m;
            result.add(new String(cur));
        }
        return;
    }
    for (char[] pair : pairs) {
        if (left == 0 && n > 1 && pair[0] == '0') {
            continue; // avoid leading zero for numbers with length > 1
        }
        cur[left] = pair[0];
        cur[right] = pair[1];
        backtrack(result, cur, left + 1, right - 1, pairs, middle, n);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for duplicate points
    int x0 = points[0][0], y0 = points[0][1];
    int x1 = points[1][0], y1 = points[1][1];
    int x2 = points[2][0], y2 = points[2][1];
    if (x0 == x1 && y0 == y1) return false;
    if (x0 == x2 && y0 == y2) return false;
    if (x1 == x2 && y1 == y2) return false;
    // Use cross product to check collinearity
    long cross = (long)(x1 - x0) * (y2 - y0) - (long)(y1 - y0) * (x2 - x0);
    return cross != 0;
}

