public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result; // Empty list for non-positive input
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10; // Go deeper in the tree
        } else {
            // If we cannot go deeper, move to the next sibling or ascend
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> res = new ArrayList<>(n);
    if (n <= 0) {
        return res;
    }
    long cur = 1;
    for (int i = 0; i < n; i++) {
        res.add((int) cur);
        if (cur * 10 <= n) {
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= n) {
            cur++;
        } else {
            while ((cur / 10) % 10 == 9) {
                cur /= 10;
            }
            cur = cur / 10 + 1;
        }
    }
    return res;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    if (n <= 0) {
        return result;
    }
    int cur = 1;
    while (result.size() < n) {
        result.add(cur);
        if (cur <= n / 10) {           // go deeper
            cur *= 10;
        } else if (cur % 10 != 9 && cur + 1 <= n) { // move to next sibling
            cur++;
        } else {                       // climb up to find next node
            while (cur / 10 % 10 == 9 || cur == n) {
                cur /= 10;
                if (cur == 0) break;
            }
            cur++;
            if (cur == 0) { // safeguard against overflow when cur becomes 0
                return result;
            }
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    result.add(current);
    for (int i = 0; i < 10; i++) {
        long next = (long) current * 10 + i;
        if (next <= n) {
            dfs((int) next, n, result);
        } else {
            break; // No need to try larger child indexes
        }
    }
}

