    // Handle null or empty input gracefully
    if (nums == null || nums.length == 0) {
        return 0;
    }

    // Count frequency of each element using a fully qualified HashMap to avoid imports
    java.util.Map<Integer, Integer> frequency = new java.util.HashMap<>();
    for (int num : nums) {
        // Add or increment the count for this number
        frequency.put(num, frequency.getOrDefault(num, 0) + 1);
    }

    // Sum only the elements that appear exactly once
    int uniqueSum = 0;
    for (int num : nums) {
        if (frequency.get(num) == 1) {
            uniqueSum += num;
        }
    }

    return uniqueSum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return n == 0 ? 0 : -1; // negative input not allowed
    }
    // Legendre's Three Square Theorem
    int m = n;
    while (m % 4 == 0) {
        m /= 4;
    }
    if (m % 8 == 7) {
        return 4;
    }
    if (isPerfectSquare(n)) {
        return 1;
    }
    if (canBeSumOfTwoSquares(n)) {
        return 2;
    }
    return 3;
}

private static boolean isPerfectSquare(int x) {
    int r = (int) Math.sqrt(x);
    return r * r == x;
}

private static boolean canBeSumOfTwoSquares(int x) {
    int limit = (int) Math.sqrt(x);
    for (int i = 1; i <= limit; i++) {
        int remaining = x - i * i;
        if (isPerfectSquare(remaining)) {
            return true;
        }
    }
    return false;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    try {
        int[] dp = new int[n + 1];
        dp[0] = 0;
        for (int i = 1; i <= n; i++) {
            dp[i] = Integer.MAX_VALUE - 1; // use -1 to avoid overflow when adding 1
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j * j <= i; j++) {
                int square = j * j;
                int candidate = dp[i - square] + 1;
                if (candidate < dp[i]) {
                    dp[i] = candidate;
                }
            }
        }
        return dp[n];
    } catch (Exception | OutOfMemoryError e) {
        throw new RuntimeException("Computation failed due to memory or runtime error", e);
    }
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int s = 1; s * s <= i; s++) {
            int square = s * s;
            if (dp[i - square] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            }
        }
    }
    return dp[n];
}

