public static String reverseWords(String s) {
    if (s == null) {
        // If input is null, return null to indicate no result
        return null;
    }

    // Trim the string to handle leading/trailing spaces, but preserve empty string case
    String trimmed = s.trim();
    if (trimmed.isEmpty()) {
        return ""; // nothing to reverse
    }

    // Split by one or more whitespace characters to get words
    String[] words = trimmed.split("\\s+");
    StringBuilder result = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        // Reverse each word
        result.append(new StringBuilder(words[i]).reverse());
        if (i < words.length - 1) {
            result.append(' ');
        }
    }

    return result.toString();
}

